import React, { useState } from "react";
import axios from "axios";

const initialState = {
  age: "",
  memory_score: "",
  brain_volume: "",
  genetic_risk: "",
  bmi: "",
  hypertension: "",
  education_level: ""
};

const PredictionPage = () => {
  const [formData, setFormData] = useState(initialState);
  const [modelType, setModelType] = useState("rf");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const values = Object.values(formData).map(Number);
    if (values.some(isNaN)) {
      alert("Please fill all fields with numeric values.");
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post("http://localhost:5000/predict", {
        inputData: values,
        modelType,
      });
      setResult(res.data.prediction === 1 ? "Alzheimer's Detected" : "No Alzheimer's Detected");
    } catch (error) {
      console.error(error);
      setResult("Prediction failed.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: "2rem", fontFamily: "Arial" }}>
      <h2>Alzheimer's Disease Prediction</h2>
      <p>Select the relevant input values based on your data. Make sure to enter numeric values in the fields.</p>

      <form onSubmit={handleSubmit}>
        {/* Age */}
        <div>
          <label>
            Age (years):{" "}
            <input
              type="number"
              name="age"
              value={formData.age}
              onChange={handleChange}
              required
              min="18"
              max="120"
              placeholder="e.g., 60"
            />
          </label>
          <small>Age should be between 18 and 120 years.</small>
        </div>

        {/* Memory Score */}
        <div>
          <label>
            Memory Score:{" "}
            <input
              type="number"
              name="memory_score"
              value={formData.memory_score}
              onChange={handleChange}
              required
              min="0"
              max="30"
              placeholder="e.g., 15"
            />
          </label>
          <small>Memory score should be between 0 and 30.</small>
        </div>

        {/* Brain Volume */}
        <div>
          <label>
            Brain Volume (in cubic centimeters):{" "}
            <input
              type="number"
              name="brain_volume"
              value={formData.brain_volume}
              onChange={handleChange}
              required
              min="500"
              max="2000"
              placeholder="e.g., 1200"
            />
          </label>
          <small>Brain volume should be between 500 and 2000 cubic centimeters.</small>
        </div>

        {/* Genetic Risk */}
        <div>
          <label>
            Genetic Risk (0 = Low, 1 = High):{" "}
            <input
              type="number"
              name="genetic_risk"
              value={formData.genetic_risk}
              onChange={handleChange}
              required
              min="0"
              max="1"
              placeholder="e.g., 1"
            />
          </label>
          <small>Genetic risk should be 0 (Low) or 1 (High).</small>
        </div>

        {/* BMI */}
        <div>
          <label>
            BMI (Body Mass Index):{" "}
            <input
              type="number"
              name="bmi"
              value={formData.bmi}
              onChange={handleChange}
              required
              min="10"
              max="50"
              placeholder="e.g., 25"
            />
          </label>
          <small>BMI should be between 10 and 50.</small>
        </div>

        {/* Hypertension */}
        <div>
          <label>
            Hypertension (0 = No, 1 = Yes):{" "}
            <input
              type="number"
              name="hypertension"
              value={formData.hypertension}
              onChange={handleChange}
              required
              min="0"
              max="1"
              placeholder="e.g., 1"
            />
          </label>
          <small>Hypertension should be 0 (No) or 1 (Yes).</small>
        </div>

        {/* Education Level */}
        <div>
          <label>
            Education Level (0 = No formal education, 1 = High school, 2 = Bachelor's, 3 = Master's/PhD):{" "}
            <input
              type="number"
              name="education_level"
              value={formData.education_level}
              onChange={handleChange}
              required
              min="0"
              max="3"
              placeholder="e.g., 2"
            />
          </label>
          <small>Education level should be between 0 (No formal education) and 3 (Master's/PhD).</small>
        </div>

        {/* Model Selection */}
        <div>
          <label>Select Model: </label>
          <select value={modelType} onChange={(e) => setModelType(e.target.value)}>
            <option value="rf">Random Forest</option>
            <option value="svm">SVM</option>
            <option value="cnn">CNN</option>
          </select>
        </div>

        <button type="submit" disabled={loading}>
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {result && (
        <div style={{ marginTop: "1rem", fontWeight: "bold" }}>
          Prediction Result: {result}
        </div>
      )}
    </div>
  );
};

export default PredictionPage;
